rule.example:

fn bail(code: i32) {
    if code != 0 {
        std::process::exit(code);
    }
}


fn scan(items: &[i32]) {
    let mut i = 0;
    while i < items.len() {
        i += 1;
    }
}


fn work(items: &[i32]) {
    for item in items {
        println!("{item}");
    }
}


fn work() {
    if let Err(_e) = might_fail() {}
}


struct Foo {
    a: A, b: B, c: C, d: D, e: E, f: F, g: G,
    h: H, i: I, j: J, k: K, l: L, m: M, n: N,
}


static mut COUNTER: i32 = 0;

fn bump() {
    unsafe { COUNTER += 1; }
}


struct Server {
    conns: i32,
    stats: i32,
}
impl Server {
    fn accept(&mut self) { self.conns += 1; }
    fn record(&mut self) { self.stats += 1; }
    // Two disjoint clusters → LCOM4 = 2 → violation
}
